      $(".navbar-toggle").click(function(){
        setTimeout(function(){
          $(".menu-item").addClass('open')  
        }, 300)
      })
    }

    $(".menu-item").click(function(){ })

    $(".menu-item a").click(function(){
      if( !$(this).attr('href') ){
        return false
      }
